<h1>Create your account</h1><?php if ( isset( $error ) ) : ?><p class="error"><?= htmlspecialchars( $error, ENT_QUOTES, 'UTF-8' ) ?></p><?php endif; ?><form method="post" action="/register"><label for="username">Username</label><input id="username" name="username" required minlength="3" maxlength="40" autocomplete="username"><label for="display_name">Display name</label><input id="display_name" name="display_name" required maxlength="80"><label for="password">Password (at least 12 characters)</label><input id="password" type="password" name="password" required minlength="12" autocomplete="new-password"><button>Create account</button></form>
